import Login from '@/views/login/login.vue'
import Vue from 'vue'
import VueRouter from 'vue-router'

Vue.use(VueRouter)

const routes = [
  {
    path: '/login',
    component: Login
  },
]

const router = new VueRouter({
  routes
})

export default router
